	@Test
	void recordsTheApiInputPreparerPassAndAllExternalSubstitutionStages() {
		Literal caller = VF.createLiteral("label", "EN");
		Literal stored = VF.createLiteral("label", "EN");
		Literal prepared = VF.createLiteral("label", "en");
		RecordingSource source = new RecordingSource(caller, stored, prepared);
		BindingSet input = bindings("x", caller);
		Filter expression = new Filter(new StatementPattern(Var.of("s"), Var.of("p", P), Var.of("x")),
				new Compare(new Lang(Var.of("x")), new ValueConstant(VF.createLiteral("EN"))));

		StringBuilder trace = new StringBuilder("API input / value preparer route\n");
		appendEvaluation(trace, "unoptimized input", expression.clone(), input, source, caller, stored, prepared);

		EvaluationStatistics statistics = new EvaluationStatistics();
		DefaultEvaluationStrategy optimizerStrategy = new DefaultEvaluationStrategy(source, null);
		StandardQueryOptimizerPipeline standard = new StandardQueryOptimizerPipeline(optimizerStrategy, source,
				statistics);
		RecordingPipeline recording = new RecordingPipeline(standard);
		optimizerStrategy.setOptimizerPipeline(recording);
		TupleExpr optimized = optimizerStrategy.optimize(new QueryRoot(expression.clone()), statistics, input);

		for (PassSnapshot snapshot : recording.snapshots) {
			trace.append("\nPASS ").append(snapshot.name()).append("\n")
					.append("  x Var: ").append(statementObjectState(snapshot.expression(), caller, stored, prepared))
					.append("\n").append(snapshot.expression()).append('\n');
			if (snapshot.name().equals(recording.firstValuedPass)) {
				appendEvaluation(trace, "first API-valued StatementPattern after " + snapshot.name(),
						snapshot.expression().clone(), input, source, caller, stored, prepared);
			}
		}
		appendEvaluation(trace, "full standard pipeline", optimized, input, source, caller, stored, prepared);
		System.out.println(trace);
		assertThat(recording.snapshots).isNotEmpty();
	}

