	private static void appendChangedPasses(StringBuilder trace, String heading, RecordingPipeline recording) {
		trace.append('\n').append(heading).append('\n');
		for (PassSnapshot snapshot : recording.snapshots) {
			trace.append("PASS ").append(snapshot.name()).append('\n').append(snapshot.expression()).append('\n');
		}
	}

	private static void appendEvaluation(StringBuilder trace, String stage, TupleExpr expression, BindingSet input,
			TripleSource source, Value first, Value second, Value third) {
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		QueryEvaluationStep step = strategy.precompile(expression);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = step.evaluate(input)) {
			while (iteration.hasNext()) {
				rows.add(new QueryBindingSet(iteration.next()));
			}
		}
		trace.append("\nSTAGE ").append(stage).append("\n  algorithms=")
				.append(joinAlgorithms(expression)).append("\n  rows=")
				.append(rows.stream().map(row -> rowSummary(row, first, second, third)).toList())
				.append("\n  plan after precompile:\n").append(expression).append('\n');
		if (source instanceof RecordingSource recording) {
			trace.append("  source events=").append(recording.events).append('\n');
			recording.events.clear();
		}
	}

	private static String rowSummary(BindingSet row, Value first, Value second, Value third) {
		List<String> names = row.getBindingNames().stream().sorted(Comparator.naturalOrder()).toList();
		List<String> parts = new ArrayList<>();
		for (String name : names) {
			parts.add(name + '=' + label(row.getValue(name), first, second, third));
		}
		return parts.toString();
	}

	private static String label(Value value, Value first, Value second, Value third) {
		if (value == null) {
			return "null";
		}
		String identity = value == first ? "first" : value == second ? "second" : value == third ? "third" : "other";
		String language = value.isLiteral() ? " lang=" + ((Literal) value).getLanguage().orElse("-") : "";
		return identity + ':' + value.stringValue() + language + '@' + Integer.toHexString(System.identityHashCode(value));
	}

	private static String joinAlgorithms(TupleExpr expression) {
		List<String> algorithms = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				algorithms.add(join.getAlgorithmName());
				super.meet(join);
			}
		});
		return algorithms.toString();
	}

	private static String statementObjectState(TupleExpr expression, Value caller, Value stored, Value prepared) {
		String[] state = { "no StatementPattern object ?x" };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				Var object = pattern.getObjectVar();
				if (object.getName().equals("x")) {
					state[0] = "hasValue=" + object.hasValue() + ", value="
							+ label(object.getValue(), caller, stored, prepared);
				}
				super.meet(pattern);
			}
		});
		return state[0];
	}

	private static BindingSetAssignment values(Value... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("x"));
		List<BindingSet> rows = new ArrayList<>();
		for (Value value : values) {
			rows.add(new ListBindingSet(List.of("x"), value));
		}
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static BindingSet bindings(String name, Value value) {
		MapBindingSet result = new MapBindingSet(1);
		result.addBinding(name, value);
		return result;
	}

	private static final class RecordingPipeline implements QueryOptimizerPipeline {
		private final StandardQueryOptimizerPipeline standard;
		private final List<PassSnapshot> snapshots = new ArrayList<>();
		private final Map<QueryOptimizer, QueryOptimizer> delegates = new IdentityHashMap<>();
		private String firstValuedPass;

		private RecordingPipeline(StandardQueryOptimizerPipeline standard) {
			this.standard = standard;
		}

		@Override
		public Iterable<QueryOptimizer> getOptimizers() {
			List<QueryOptimizer> result = new ArrayList<>();
			for (QueryOptimizer delegate : standard.getOptimizers()) {
				QueryOptimizer wrapper = new QueryOptimizer() {
					@Override
					public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
						String beforePlan = tupleExpr.toString();
						String before = statementObjectState(tupleExpr, null, null, null);
						delegate.optimize(tupleExpr, dataset, bindings);
						String afterPlan = tupleExpr.toString();
						String after = statementObjectState(tupleExpr, null, null, null);
						if (!beforePlan.equals(afterPlan)) {
							snapshots.add(new PassSnapshot(delegate.getClass().getSimpleName(), tupleExpr.clone()));
						}
						if (firstValuedPass == null && before.contains("hasValue=false")
								&& after.contains("hasValue=true")) {
							firstValuedPass = delegate.getClass().getSimpleName();
						}
					}
				};
				delegates.put(wrapper, delegate);
				result.add(wrapper);
			}
			return result;
		}

		@Override
		public BindingSet getOptimizerInputBindings(QueryOptimizer optimizer, BindingSet initialBindings) {
			return standard.getOptimizerInputBindings(delegates.get(optimizer), initialBindings);
		}
	}

	private record PassSnapshot(String name, TupleExpr expression) {
	}

	private static final class RecordingSource implements TripleSource {
		private final Value caller;
		private final Value prepared;
		private final LinkedHashModel data = new LinkedHashModel();
		private final List<String> events = new ArrayList<>();

		private RecordingSource(Value caller, Value stored, Value prepared) {
			this.caller = caller;
			this.prepared = prepared;
			data.add(S, P, stored);
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject,
				org.eclipse.rdf4j.model.IRI predicate, Value object, Resource... contexts) {
			events.add("lookup object=" + label(object, caller, null, prepared));
			return new CloseableIteratorIteration<>(data.getStatements(subject, predicate, object, contexts).iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		@Override
		public java.util.function.Function<Value, Value> getValuePreparer() {
			return value -> {
				events.add("prepare=" + label(value, caller, null, prepared));
				return value == caller || value.equals(caller) ? prepared : value;
			};
		}
	}
